from tkinter import Tk, Canvas, Entry, Text, Button, PhotoImage, Label


OUTPUT_PATH = Path(__file__).parent
ASSETS_PATH = OUTPUT_PATH / "assets/frame0"


def relative_to_assets(path: str) -> Path:
    return ASSETS_PATH / Path(path)


window = Tk()
window.geometry("1280x720")
window.configure(bg = "#FFFFFF")

window.update_idletasks()
screen_width = window.winfo_screenwidth()
screen_height = window.winfo_screenheight()
window_width = 1280
window_height = 720
x_position = (screen_width - window_width) // 2
y_position = (screen_height - window_height) // 2
window.geometry(f"{window_width}x{window_height}+{x_position}+{y_position}")

canvas = Canvas(
    window,
    bg = "#FFFFFF",
    height = 720,
    width = 1280,
    bd = 0,
    highlightthickness = 0,
    relief = "ridge"
)

canvas.place(x = 0, y = 0)
image_image_1 = PhotoImage(
    file=relative_to_assets("image_1.png"))
image_1 = canvas.create_image(
    640.0,
    360.0,
    image=image_image_1
)

canvas.create_text(
    350.0, #vertical
    122.0, #horizontal
    anchor="nw",
    text="ʙʀᴀɪɴʙᴏᴀʀᴅ",
    fill="#FFFFFF",
    font=("Inter ExtraBold", 128 * -1)
)

image_image_2 = PhotoImage(
    file=relative_to_assets("image_2.png"))
image_2 = canvas.create_image(
    639.0,
    317.0,
    image=image_image_2
)

button_image_normal = PhotoImage(file=relative_to_assets("button_1.png"))  # Imagen normal
button_image_hover = PhotoImage(file=relative_to_assets("button_1_hover.png"))  # Imagen hover
button_image_pressed = PhotoImage(file=relative_to_assets("button_1_pressed.png"))  # Imagen clic

# Crear el botón como Label
button_1 = Label(
    window,
    image=button_image_normal,
    borderwidth=0,
    highlightthickness=0,
    relief="flat"
)

button_1.place(x=431.0, y=375.0, width=426.0, height=157.0)

# Funciones para cambiar la imagen en los eventos del mouse
def on_enter(event):
    button_1.config(image=button_image_hover)

def on_leave(event):
    button_1.config(image=button_image_normal)

def on_press(event):
    button_1.config(image=button_image_pressed)

def on_release(event):
    button_1.config(image=button_image_hover)  # O vuelve a la imagen normal si no quieres hover

# Vincular eventos al botón
button_1.bind("<Enter>", on_enter)
button_1.bind("<Leave>", on_leave)
button_1.bind("<ButtonPress-1>", on_press)
button_1.bind("<ButtonRelease-1>", on_release)

# Acción del botón (cuando se suelta)
button_1.bind("<ButtonRelease-1>", lambda event: print("button_1 clicked"))

window.resizable(False, False)
window.mainloop()